"""4차(2026~2030) 계산 엔진  —  김서진, 2026-11-16 (3차본) / 수정: 임채은 2026-11-18 (가격 시나리오, 편향 보정, SK 판교 할당 이전)

예측 배출을 넣으면 분석단위 × 연도 × 가격 시나리오마다
  모자라는 양 → 이월 사용 → (상쇄·차입) → 경매·시장 구매 → 탄소비용 (→ 판매수입, 순비용)
을 계산해 계산 결과표를 만든다.  ← 엔진의 본 결과물 (결과표())

참고용 (가설 담당이 바꿔 써도 됨)
  - 지표(): 결과표 열로 만든 지표 예시 (실효탄소가격, 무상할당가치, 위험도 등)
  - 민감도_결과표(): 가정을 하나씩 바꿔 다시 계산한 결과

입력 (11:15 폴더 기준, 읽기만 함. 팀 파일은 바꾸지 않음)
  - 06_모델링/배출예측/results/최종_배출예측_2026_2030_임채은.csv   예측 배출 (중앙, P10, P90)
  - 05_전처리/data/모델링_패널_20261114.csv                        사전·유상분·무상할당·이월·재무
  - 05_전처리/data/분석단위_표_20261114.csv, 연도_표_20261114.csv

설명: 00_계산엔진_설명_김서진.html, 06_계산엔진_김서진.ipynb
"""
from __future__ import annotations

from dataclasses import dataclass, field, asdict
from pathlib import Path

import numpy as np
import pandas as pd

YEARS = [2026, 2027, 2028, 2029, 2030]


def 직선(시작: float, 끝: float) -> dict:
    """2026년 시작값에서 2030년 끝값까지 직선으로 잇는 연도별 가격."""
    return {y: 시작 + (끝 - 시작) * i / 4 for i, y in enumerate(YEARS)}


# 가격 시나리오 (원/톤)
# 수정: 임채은 11/18 — 팀 확정안으로 교체 (이전: 낮음 1만 / 중간 29,500 / 높음 → 6만 / EU수준 → 11.5만, 2026년 29,500원 시작)
#   2026년 = 실제 KAU 연평균 (05_전처리 연도_표 KAU_연평균가, 11/14 기준. 연말에 갱신)
#   2027~2030년 = 현재가 3만 원(2026.9~11월 월평균)에서 2030년 값까지 직선
KAU_2026_실제 = 21_873
def 경로(끝: float, 시작: float = 30_000) -> dict:
    """2026년은 실제 연평균, 2027~2030년은 시작값(2026년 자리)에서 끝값까지 직선."""
    p = 직선(시작, 끝)
    p[2026] = KAU_2026_실제
    return p

가격시나리오 = {
    "3차 회귀": 경로(10_000),       # 2023~2025년 KAU 실제 연평균 (10,033 / 9,276 / 9,230원) 반올림
    "현재 유지": 경로(30_000),      # 2026년 9~11월 KAU 월평균 (30,234 / 30,036 / 29,666원) 반올림
    "IEA 현행정책": 경로(78_000),   # IEA 모델 문서 2024 표 2.4: 한국 2030년 $56 × 1,400원
    "전환 필요": 경로(115_000),     # 팀원 안의 EU 수준 (H4 자료). PLANiT 산업전환 가격대 9만~12만 원 안
}


# ─────────────────────────── 가정 (바꿀 수 있는 값) ───────────────────────────
@dataclass
class 가정:
    # 이월: 잉여는 N/(N+1)까지 이월, 나머지는 판다고 봄 (가정 기록 10-1번, 할당계획 33~34쪽 해석, 임시)
    이월_N: dict = field(default_factory=lambda: {2026: 6, 2027: 7, 2028: 8, 2029: 9, 2030: 10})
    이월_시작잔고_사용: bool = True      # 2025년 이월 잔고(3차 → 4차)를 쓰나 (가정 기록 10번)
    # 상쇄: 그해 배출(제출량)의 몇 %까지 상쇄로 채우나. 기본 0 (모델링 가이드 4-2), 민감도 5% (할당계획 p.37)
    상쇄_한도: float = 0.0
    상쇄_가격비율: float = 1.0           # KAU 대비 상쇄배출권 가격. 이지 확인 대기
    # 차입: 그해 제출량의 몇 %까지 다음 해 할당을 당겨 쓰나. 다음 해에 갚음. 기본 0, 민감도 30% (가이드 4-2)
    차입_한도: float = 0.0
    # 경매가 = 시장가 × 비율. 기본 1.0 (가정 기록 12번), 민감도 0.9 / 1.1
    경매가_비율: float = 1.0
    # 할당 열: 무상할당(기본) / 무상할당_사전만 / 무상할당_보정전 / 무상할당_집단에너지발전비율
    무상할당_열: str = "무상할당"
    # 배출 열: 예측_배출(중앙, 기본) / 예측_P10 / 예측_P90 (P10·P90은 회사 하나 기준 범위. 합계에는 쓰지 않음)
    배출_열: str = "예측_배출"
    # 합계 범위용: 모든 단위 배출에 같은 배율 (백테스트 합계 오차 최대 4.9% → ±5%)
    배출_배율: float = 1.0
    # 연도별 백테스트 편향 보정: 예측 ÷ (1 + 편향_h)
    # 수정: 임채은 11/18 — 업종별 편향(단위 적은 업종이 불안정, 연도 구분 없음) 대신
    #   06_모델링/배출예측/results/연도별_편향_임채은.csv 의 발전 외 편향을
    #   발전 외 + 예측방법 "M1w + B1 연도별 혼합" 행에만 적용. 발전은 보정하지 않음 (시험마다 +3 ~ +34%로 불안정)
    배출_편향보정: bool = False
    # 등급 기준 (위험도)
    고위험: float = 0.30
    중위험: float = 0.10

    def 표(self) -> pd.DataFrame:
        return pd.DataFrame([(k, str(v)) for k, v in asdict(self).items()], columns=["가정", "값"])


# 민감도: 기본에서 하나씩만 바꿈 (모델링 가이드 4-2 + 경매가)
민감도 = {
    "기본": 가정(),
    "배출_P10": 가정(배출_열="예측_P10"),
    "배출_P90": 가정(배출_열="예측_P90"),
    "배출_편향보정": 가정(배출_편향보정=True),
    "배출_합계-5%": 가정(배출_배율=0.95),
    "배출_합계+5%": 가정(배출_배율=1.05),
    "상쇄5%": 가정(상쇄_한도=0.05),
    "차입30%": 가정(차입_한도=0.30),
    "할당_사전만": 가정(무상할당_열="무상할당_사전만"),
    "할당_보정전": 가정(무상할당_열="무상할당_보정전"),
    "할당_집단에너지발전비율": 가정(무상할당_열="무상할당_집단에너지발전비율"),
    "3차잔고_안씀": 가정(이월_시작잔고_사용=False),
    "경매가0.9": 가정(경매가_비율=0.9),
    "경매가1.1": 가정(경매가_비율=1.1),
}


# ─────────────────────────── 입력 읽기 ───────────────────────────
# (넘긴 단위, 받은 단위, 옮기는 비율) — 수정: 임채은 11/18. 빈 목록이면 이전 없음
할당이전 = [("F1644", "F1649", 1 - 21_186 / 116_858)]   # 에스케이㈜ 판교 데이터센터 → SK브로드밴드 (2025.06 양도), 약 81.9%


def 입력_읽기(root: Path) -> dict:
    root = Path(root)
    p = pd.read_csv(root / "05_전처리/data/모델링_패널_20261114.csv", encoding="utf-8-sig", low_memory=False)
    yt = pd.read_csv(root / "05_전처리/data/연도_표_20261114.csv", encoding="utf-8-sig")
    ut = pd.read_csv(root / "05_전처리/data/분석단위_표_20261114.csv", encoding="utf-8-sig")
    fc = pd.read_csv(root / "06_모델링/배출예측/results/최종_배출예측_2026_2030_임채은.csv", encoding="utf-8-sig")

    p["플래그_예측대상"] = p["플래그_예측대상"].astype(bool)
    units = sorted(p.loc[p["플래그_예측대상"], "분석단위ID"].unique())
    q = p[p["분석단위ID"].isin(units)]

    info = q[q["연도"] == 2026].set_index("분석단위ID")[
        ["분석업종", "기관유형", "플래그_공공비영리", "플래그_지자체", "매출_3년평균", "영업이익_3년평균", "영업이익률_3년평균", "재무상태"]]
    info = info.join(ut.set_index("분석단위ID")[["분석단위명", "시도", "4차_신규"]])
    info["제외사유"] = np.select(
        [info["플래그_지자체"].astype(bool), info["영업이익_3년평균"].isna() & (info["기관유형"] != "민간"),
         info["영업이익_3년평균"].isna()],
        ["지자체 (재무 지표 없음)", f"재무 없음 ({'공공·비영리'})", "재무 없음 (미수집·미공개)"], default="")

    alloc_cols = ["사전", "순할당_이전반영", "유상분", "무상할당", "무상할당_사전만", "무상할당_보정전", "무상할당_집단에너지발전비율"]
    alloc = q[q["연도"].isin(YEARS)].set_index(["분석단위ID", "연도"])[alloc_cols]
    # 수정: 임채은 11/18 — 사업장 양도에 따른 할당 이전
    #   에스케이㈜(F1644)는 판교 데이터센터를 2025.06 SK브로드밴드(F1649)로 넘겼는데, 4차 할당은 판교 이력 기준으로 에스케이㈜에 나옴
    #   → 2025년 선례(에스케이㈜ 할당 116,858 → 21,186 t, 18.1%만 남음)대로 4차 할당의 81.9%를 SK브로드밴드로 옮김
    #   두 회사 모두 유상 15%라 7개 열을 같은 비율로 옮겨도 서로 맞음. 4차 할당 합계는 그대로
    for 넘김, 받음, 비율 in 할당이전:
        if 넘김 in alloc.index.get_level_values(0) and 받음 in alloc.index.get_level_values(0):
            mv = alloc.loc[넘김].mul(비율)
            alloc.loc[(넘김, slice(None)), :] = (alloc.loc[넘김] - mv).to_numpy()
            alloc.loc[(받음, slice(None)), :] = (alloc.loc[받음] + mv).to_numpy()

    y25 = q[q["연도"] == 2025].set_index("분석단위ID")
    start = pd.DataFrame(index=units)
    start["잔고_2025"] = y25["이월_할당배출권"].reindex(units)
    start["무상할당_2025"] = y25["무상할당"].reindex(units)          # 3차 규칙 = 2025 순할당 × (1 − 유상 10%)
    past = q[q["연도"].between(2023, 2025)].merge(yt[["연도", "KAU_연평균가"]], on="연도", suffixes=("", "_y"))
    past["비용"] = (past["보정_배출량"] - past["무상할당"]).clip(lower=0) * past["KAU_연평균가_y"]
    start["기존비용_3년평균"] = past.groupby("분석단위ID")["비용"].mean().reindex(units).fillna(0)

    fc = fc[fc["분석단위ID"].isin(units)].set_index(["분석단위ID", "연도"])[["예측_배출", "예측_P10", "예측_P90", "예측방법"]]
    # 연도별 백테스트 편향 (+ = 예측이 실제보다 많았음). 수정: 임채은 11/18 (이전: 백테스트_업종별_임채은.csv 업종별 편향)
    bt = pd.read_csv(root / "06_모델링/배출예측/results/연도별_편향_임채은.csv", encoding="utf-8-sig").set_index("연도")["편향_발전외(%)"] / 100
    sector = fc.index.get_level_values(0).map(info["분석업종"])
    apply_ = (sector != "발전") & (fc["예측방법"] == "M1w + B1 연도별 혼합").to_numpy()
    bias = pd.Series(np.where(apply_, fc.index.get_level_values(1).map(bt).to_numpy(), 0.0), index=fc.index)   # (분석단위ID, 연도)별
    return {"units": units, "info": info, "alloc": alloc, "start": start, "forecast": fc, "panel": p, "year_table": yt, "bias": bias}


# ─────────────────────────── 엔진 본체 ───────────────────────────
def 계산(inp: dict, 가격: dict, a: 가정 | None = None, 배출: pd.Series | None = None) -> pd.DataFrame:
    """한 시나리오 계산. 가격: {연도: 원/톤}. 배출을 주지 않으면 a.배출_열의 예측을 씀."""
    a = a or 가정()
    if 배출 is None:
        배출 = inp["forecast"][a.배출_열] * a.배출_배율
        if a.배출_편향보정:
            배출 = 배출 / (1 + inp["bias"].reindex(배출.index).fillna(0.0).to_numpy())   # 수정: 임채은 11/18 (단위 × 연도별)
    al, st = inp["alloc"], inp["start"]
    rows = []
    for u in inp["units"]:
        잔고 = float(st.at[u, "잔고_2025"]) if (a.이월_시작잔고_사용 and pd.notna(st.at[u, "잔고_2025"])) else 0.0
        상환 = 0.0
        for y in YEARS:
            e = float(배출.get((u, y), np.nan))
            사전 = float(al.at[(u, y), "사전"])
            무상 = float(al.at[(u, y), a.무상할당_열])
            유상 = max(float(al.at[(u, y), "순할당_이전반영"]) - 무상, 0.0)   # 이 할당 열 기준 유상분
            P = 가격[y]
            잔고_연초 = 잔고

            모자람 = e - 무상                      # 유상분 포함 (팀 결정 3번, 가이드 4-1)
            필요 = 모자람 + 상환                    # 전년 차입 상환
            이월사용 = min(잔고, max(필요, 0.0))
            잔고 -= 이월사용
            남은 = max(필요, 0.0) - 이월사용

            잉여 = max(-필요, 0.0)
            N = a.이월_N[y]
            잉여_이월 = 잉여 * N / (N + 1)
            잉여_판매 = 잉여 - 잉여_이월
            잔고 += 잉여_이월

            상쇄 = min(남은, a.상쇄_한도 * e) if a.상쇄_한도 > 0 else 0.0
            남은 -= 상쇄
            차입 = min(남은, a.차입_한도 * e) if (a.차입_한도 > 0 and y < YEARS[-1]) else 0.0   # 2030년은 5차에서 못 당김
            남은 -= 차입
            상환 = 차입

            구매_경매 = min(남은, 유상)             # 자기 유상분까지는 경매에서 (근사)
            구매_시장 = 남은 - 구매_경매
            비용_경매 = 구매_경매 * P * a.경매가_비율
            비용_시장 = 구매_시장 * P
            비용_상쇄 = 상쇄 * P * a.상쇄_가격비율
            rows.append((u, y, e, 사전, 무상, 유상, 모자람, 잔고_연초, 이월사용, 잉여_이월, 잉여_판매, 잔고,
                         상쇄, 차입, 구매_경매, 구매_시장, P, 비용_경매, 비용_시장, 비용_상쇄))
    r = pd.DataFrame(rows, columns=["분석단위ID", "연도", "예측배출", "사전할당", "무상할당", "유상분", "모자라는양",
                                     "이월잔고_연초", "이월사용", "잉여_이월", "잉여_판매", "이월잔고",
                                     "상쇄", "차입", "구매_경매", "구매_시장", "가격", "비용_경매", "비용_시장", "비용_상쇄"])
    r["구매량"] = r["구매_경매"] + r["구매_시장"]
    r["탄소비용"] = r["비용_경매"] + r["비용_시장"] + r["비용_상쇄"]
    r["판매수입"] = r["잉여_판매"] * r["가격"]          # 잉여 중 이월 한도 밖이라 판 양 × 가격
    r["순비용"] = r["탄소비용"] - r["판매수입"]
    # 단위 정보·재무 재료 붙이기 (지표는 가설 담당이 이 열로 만듦)
    info, st, fc = inp["info"], inp["start"], inp["forecast"]
    r = r.join(info, on="분석단위ID").join(st[["무상할당_2025", "기존비용_3년평균"]], on="분석단위ID")
    r = r.join(fc[["예측_P10", "예측_P90"]].rename(columns={"예측_P10": "예측배출_P10", "예측_P90": "예측배출_P90"}),
               on=["분석단위ID", "연도"])
    return r


def 지표(r: pd.DataFrame, a: 가정 | None = None) -> pd.DataFrame:
    """참고: 결과표 열로 만든 지표 예시. 가설 담당이 식을 바꿔 써도 됨 (구매량·탄소비용은 안 바뀜)."""
    a = a or 가정()
    r = r.copy()
    op, sl = r["영업이익_3년평균"], r["매출_3년평균"]
    E = r["예측배출"].where(r["예측배출"] > 0)

    # H4 실효 탄소가격
    r["실효탄소가격"] = r["탄소비용"] / E
    r["실효가격_비율"] = r["실효탄소가격"] / r["가격"]
    # H5 무상할당 = 숨은 보조금 (가치는 시장가 기준)
    r["무상할당가치"] = r["무상할당"].clip(lower=0) * r["가격"]
    r["무상가치비율"] = r["무상할당가치"] / op.where(op > 0)
    r["남은배출권이득"] = (r["무상할당"] - r["예측배출"]).clip(lower=0) * r["가격"]
    # H7 부담
    r["이익률감소폭"] = r["탄소비용"] / sl.where(sl > 0)
    r["반영후이익률"] = r["영업이익률_3년평균"] - r["이익률감소폭"]
    r["위험도"] = r["탄소비용"] / op.where(op > 0)
    r["적자전환"] = (op > 0) & (op - r["탄소비용"] < 0)
    r["추가부담"] = r["탄소비용"] - r["기존비용_3년평균"]
    r["적자전환_추가부담기준"] = (op > 0) & (op - r["추가부담"] < 0)
    # H7·H4 비교: 같은 배출·가격에서 3차 규칙(2025년 무상할당) vs 4차 규칙 (둘 다 이월 없음)
    r["구매량_3차규칙"] = (r["예측배출"] - r["무상할당_2025"]).clip(lower=0).where(r["무상할당_2025"].notna())
    r["구매량_4차규칙"] = (r["예측배출"] - r["무상할당"]).clip(lower=0)
    r["실효탄소가격_3차규칙"] = r["구매량_3차규칙"] * r["가격"] / E
    r["실효탄소가격_4차규칙"] = r["구매량_4차규칙"] * r["가격"] / E

    fin = op.notna()
    r["등급"] = np.select(
        [~fin, r["탄소비용"] <= 0, op <= 0, r["위험도"] >= a.고위험, r["위험도"] >= a.중위험],
        ["별도 (재무 없음)", "⑤ 비용 없음", "① 고위험(적자)", "② 고위험", "③ 중위험"], default="④ 저위험")
    return r


# ─────────────────────────── 요약 ───────────────────────────
def 요약(r: pd.DataFrame) -> pd.DataFrame:
    g = r.groupby("연도")
    s = pd.DataFrame({
        "예측배출": g["예측배출"].sum(),
        "사전할당(총량)": g["사전할당"].sum(),
        "무상할당": g["무상할당"].sum(),
        "갭_총량": g["예측배출"].sum() - g["사전할당"].sum(),
        "갭_무상(구매압력)": g["예측배출"].sum() - g["무상할당"].sum(),
        "이월사용": g["이월사용"].sum(),
        "상쇄": g["상쇄"].sum(),
        "차입": g["차입"].sum(),
        "구매_경매": g["구매_경매"].sum(),
        "구매_시장": g["구매_시장"].sum(),
        "구매량": g["구매량"].sum(),
        "잉여_판매": g["잉여_판매"].sum(),
        "이월잔고": g["이월잔고"].sum(),
        "탄소비용": g["탄소비용"].sum(),
        "판매수입": g["판매수입"].sum(),
        "순비용": g["순비용"].sum(),
    })
    s["누수(총량 밖 공급)"] = s["이월사용"] + s["상쇄"] + s["차입"]
    return s


# ─────────────────────────── 결과표 ───────────────────────────
키_열 = ["분석단위ID", "연도", "가격시나리오"]
결과표_열 = 키_열 + [
    "분석단위명", "분석업종", "기관유형", "시도", "플래그_공공비영리", "4차_신규",
    "예측배출", "예측배출_P10", "예측배출_P90",
    "사전할당", "무상할당", "유상분", "무상할당_2025",
    "모자라는양", "이월잔고_연초", "이월사용", "잉여_이월", "잉여_판매", "이월잔고",
    "상쇄", "차입", "구매_경매", "구매_시장", "구매량",
    "가격", "비용_경매", "비용_시장", "비용_상쇄", "탄소비용", "판매수입", "순비용",
    "매출_3년평균", "영업이익_3년평균", "영업이익률_3년평균", "기존비용_3년평균", "제외사유"]
지표_열 = ["실효탄소가격", "실효가격_비율", "무상할당가치", "무상가치비율", "남은배출권이득",
          "이익률감소폭", "반영후이익률", "위험도", "적자전환", "추가부담", "적자전환_추가부담기준", "등급",
          "구매량_3차규칙", "구매량_4차규칙", "실효탄소가격_3차규칙", "실효탄소가격_4차규칙"]


def 결과표(inp: dict, 가격들: dict | None = None, a: 가정 | None = None) -> pd.DataFrame:
    """본 결과물: 분석단위 × 연도 × 가격 시나리오 (기본 가정)."""
    out = []
    for p_name, path in (가격들 or 가격시나리오).items():
        r = 계산(inp, path, a)
        r["가격시나리오"] = p_name
        out.append(r[결과표_열])
    return pd.concat(out, ignore_index=True)


def 지표표(T: pd.DataFrame, a: 가정 | None = None) -> pd.DataFrame:
    """참고: 결과표에 지표 예시를 붙여 키 + 지표 열만 돌려줌."""
    return 지표(T, a)[키_열 + 지표_열]


def 민감도_결과표(inp: dict, 가격들: dict | None = None, 민감도들: dict | None = None) -> pd.DataFrame:
    """참고: 가정을 하나씩 바꾼 결과표를 이어 붙임 (민감도 열 추가)."""
    out = []
    for s_name, a in (민감도들 or 민감도).items():
        T = 결과표(inp, 가격들, a)
        T.insert(3, "민감도", s_name)
        out.append(T)
    return pd.concat(out, ignore_index=True)
